import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';
import 'dart:io';

class FileStoragePage extends StatefulWidget {
  const FileStoragePage({Key? key}) : super(key: key);

  @override
  _FileStoragePageState createState() => _FileStoragePageState();
}

class _FileStoragePageState extends State<FileStoragePage> {
  final TextEditingController _controller = TextEditingController();
  String _savedContent = "Nothing saved yet.";

  // --- File Helper Methods ---
  Future<String> get _localPath async {
    final directory = await getApplicationDocumentsDirectory();
    return directory.path;
  }

  Future<File> get _localFile async {
    final path = await _localPath;
    return File('$path/my_data.txt');
  }

  Future<void> _writeData() async {
    final file = await _localFile;
    await file.writeAsString(_controller.text);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Saved to file!')),
    );
  }

  Future<void> _readData() async {
    try {
      final file = await _localFile;
      final contents = await file.readAsString();
      setState(() {
        _savedContent = contents.isNotEmpty ? contents : "File is empty.";
      });
    } catch (e) {
      setState(() {
        _savedContent = "Could not read file.";
      });
    }
  }
  // --- End Helper Methods ---


  @override
  void initState() {
    super.initState();
    _readData(); // Load any saved data on startup
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('File Storage Demo')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            TextField(
              controller: _controller,
              decoration: InputDecoration(labelText: 'Enter text to save'),
            ),
            SizedBox(height: 20),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton(
                  onPressed: _writeData,
                  child: Text('Save to File'),
                ),
                ElevatedButton(
                  onPressed: _readData,
                  child: Text('Load from File'),
                ),
              ],
            ),
            SizedBox(height: 40),
            Text('Content saved in file:', style: Theme.of(context).textTheme.titleLarge),
            SizedBox(height: 10),
            Text(_savedContent),
          ],
        ),
      ),
    );
  }
}

